fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let mut res = Vec::new();
    
    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            res.push(delim); // Add the delimiter before every element except the first
        }
        res.push(num); // Add the current element
    }
    
    res
}

fn main() {
    // Example usage
    let numbers = vec![1, 2, 3];
    let delim = 0;
    let result = intersperse(&numbers, delim);
    println!("{:?}", result); // Output: [1, 0, 2, 0, 3]
}